def fib(n):
    a, b = 0, 1
    result = []
    for _ in range(n):
        result.append(str(a))
        a, b = b, a + b
    return ",".join(result)

print(fib(25))

#!/usr/bin/env python3
"""Read numbers.txt, find primes, print count, sum, and list."""

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

with open('/tmp/wolffish-orch-w2/numbers.txt') as f:
    numbers = [int(line.strip()) for line in f if line.strip()]

primes = [n for n in numbers if is_prime(n)]

count = len(primes)
total = sum(primes)

print(f"Count of primes: {count}")
print(f"Sum of primes: {total}")
print(f"Primes: {primes}")
